parameters.jsCode:
// Paste a fixture's { ev, metrics, rule_flags } object below to test that scenario.
// Leave as null to use each A2 tool's built-in dev fixture (the declining_safety case).
const case_file = null;
return [{ json: { case_file } }];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "quality_band": {
      "type": "string",
      "enum": [
        "good",
        "fair",
        "poor"
      ],
      "description": "Copied verbatim from the case file metrics."
    },
    "key_findings": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "minItems": 1,
      "maxItems": 3,
      "description": "1-3 findings, each quoting a fault label exactly as the tools returned it."
    },
    "summary_for_physio": {
      "type": "string",
      "description": "2-3 sentence summary for the physiotherapist."
    }
  },
  "required": [
    "quality_band",
    "key_findings",
    "summary_for_physio"
  ],
  "additionalProperties": false
}
